"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { useMemo } from "react"

import { FieldGroup } from "@/components/ui/field"
import {
  type Facility,
  type Program,
  type RightType,
  type Role,
  type RoleAssignment,
  rightLabel,
  roleTypeOf,
  type SupervisoryNode,
} from "@/components/blocks/openlmis/role-assignments/role-assignments"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { Callout } from "@/components/openlmis/callout"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  ComboboxField,
  FieldSkeleton,
} from "@/components/openlmis/form-fields/form-fields"

import {
  EMPTY_ROLE_FORM,
  type RoleFormValues,
  roleFormSchema,
  toRoleAssignment,
} from "@/components/openlmis/user-roles-page/role-form"

const TYPE_LABEL: Record<RightType, string> = {
  SUPERVISION: "Supervision",
  ORDER_FULFILLMENT: "Fulfillment",
  REPORTS: "Reports",
  GENERAL_ADMIN: "Administration",
}

/** The dialog's choices; a list left undefined shows a skeleton in its field. */
export type AddRoleOptions = {
  roles: readonly Role[] | undefined
  programs: readonly Program[] | undefined
  nodes: readonly SupervisoryNode[] | undefined
  facilities: readonly Facility[] | undefined
}

type AddRoleDialogProps = AddRoleOptions & {
  /** The type of role being added; the dialog is open while it is set. */
  type: RightType | undefined
  /** The roles the user holds now, so the same one cannot be added twice. */
  assigned: readonly RoleAssignment[]
  username: string
  hasHomeFacility: boolean
  onAdd: (assignment: RoleAssignment) => void
  onClose: () => void
}

export function AddRoleDialog({ type, onClose, ...props }: AddRoleDialogProps) {
  const { shown, dialogProps } = useDialogTarget(type, onClose)

  return (
    <FormDialog {...dialogProps()}>
      {shown && (
        <AddRoleContent key={shown} onDone={onClose} type={shown} {...props} />
      )}
    </FormDialog>
  )
}

type ContentProps = Omit<AddRoleDialogProps, "type" | "onClose"> & {
  type: RightType
  onDone: () => void
}

const byName = <T extends { name: string }>(a: T, b: T) =>
  a.name.localeCompare(b.name)

function AddRoleContent({ roles, ...props }: ContentProps) {
  const { type, username } = props
  const ofType = useMemo(
    () =>
      // oxlint-disable-next-line unicorn/no-array-sort -- sorts the fresh filtered array
      roles?.filter((role) => roleTypeOf(role) === type).sort(byName),
    [roles, type]
  )

  if (!ofType) {
    return (
      <>
        <AddRoleHeader type={type} username={username} />
        <FormDialogBody>
          <div aria-busy>
            <FieldGroup>
              {type === "SUPERVISION" && (
                <FieldSkeleton label="Program" required />
              )}
              <FieldSkeleton label="Role" required />
            </FieldGroup>
          </div>
        </FormDialogBody>
        <FormDialogFooter>
          <FormDialogCancel />
          <FormDialogSubmit disabled>Add Role</FormDialogSubmit>
        </FormDialogFooter>
      </>
    )
  }
  return <AddRoleForm {...props} roles={ofType} />
}

function AddRoleHeader({
  type,
  username,
}: {
  type: RightType
  username: string
}) {
  return (
    <FormDialogHeader>
      <FormDialogTitle>Add {TYPE_LABEL[type]} Role</FormDialogTitle>
      <FormDialogDescription>
        Choose a {TYPE_LABEL[type].toLowerCase()} role to grant to {username}.
      </FormDialogDescription>
    </FormDialogHeader>
  )
}

function AddRoleForm({
  type,
  roles,
  assigned,
  username,
  hasHomeFacility,
  onAdd,
  onDone,
  programs,
  nodes,
  facilities,
}: Omit<ContentProps, "roles"> & { roles: Role[] }) {
  const schema = useMemo(() => roleFormSchema(type, assigned), [type, assigned])

  const form = useAppForm({
    // A type with a single role has nothing to choose, so it starts chosen.
    defaultValues: {
      ...EMPTY_ROLE_FORM,
      roleId: roles.length === 1 ? (roles[0]?.id ?? null) : null,
    } satisfies RoleFormValues,
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => {
      onAdd(toRoleAssignment(type, value))
      onDone()
    },
  })

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <AddRoleHeader type={type} username={username} />
      <FormDialogBody>
        <FieldGroup>
          {type === "SUPERVISION" && (
            <>
              <form.AppField name="programId">
                {() => <ProgramField programs={programs} />}
              </form.AppField>
              <form.AppField name="supervisoryNodeId">
                {() => <NodeField facilities={facilities} nodes={nodes} />}
              </form.AppField>
            </>
          )}
          {type === "ORDER_FULFILLMENT" && (
            <form.AppField name="warehouseId">
              {() => <FacilityField facilities={facilities} />}
            </form.AppField>
          )}
          <form.AppField name="roleId">
            {(field) => <RoleField roleId={field.state.value} roles={roles} />}
          </form.AppField>
          {type === "SUPERVISION" && !hasHomeFacility && (
            <form.Subscribe
              selector={(state) => state.values.supervisoryNodeId}
            >
              {(nodeId) =>
                !nodeId && (
                  <Callout title="No Home Facility" tone="warning">
                    Without a supervisory node this role applies at the home
                    facility, and {username} has none, so it grants nothing
                    until one is set.
                  </Callout>
                )
              }
            </form.Subscribe>
          )}
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit>Add Role</FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

/** Hints how many there are, since the list shows the first 50 until the user types. */
const searchHint = (count: number, noun: string) =>
  `Type to search ${count} ${noun}.`

function ProgramField({ programs }: Pick<AddRoleOptions, "programs">) {
  const items = useMemo(() => {
    const sorted = [...(programs ?? [])]
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts a copy
    sorted.sort(byName)
    return sorted.map((program) => ({ value: program.id, label: program.name }))
  }, [programs])
  if (!programs) return <FieldSkeleton label="Program" required />
  return (
    <ComboboxField
      clearLabel="Clear Program"
      emptyMessage="No programs found."
      items={items}
      label="Program"
      placeholder="Search Programs..."
      required
    />
  )
}

/** Each node with its facility, as OpenLMIS names them, e.g. "FP Approval Point (Balaka)". */
function NodeField({
  nodes,
  facilities,
}: Pick<AddRoleOptions, "nodes" | "facilities">) {
  const items = useMemo(() => {
    const names = new Map(
      (facilities ?? []).map((facility) => [facility.id, facility.name])
    )
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts a copy
    return [...(nodes ?? [])].sort(byName).map((node) => {
      const facility = node.facility && names.get(node.facility.id)
      return {
        value: node.id,
        label: facility ? `${node.name} (${facility})` : node.name,
      }
    })
  }, [nodes, facilities])

  if (!nodes || !facilities) return <FieldSkeleton label="Supervisory Node" />
  return (
    <ComboboxField
      clearLabel="Clear Supervisory Node"
      description={`${searchHint(items.length, "nodes")} Leave empty for the home facility.`}
      emptyMessage="No supervisory nodes found."
      items={items}
      label="Supervisory Node"
      placeholder="Search Supervisory Nodes..."
    />
  )
}

function FacilityField({ facilities }: Pick<AddRoleOptions, "facilities">) {
  const items = useMemo(
    () =>
      // oxlint-disable-next-line unicorn/no-array-sort -- sorts a copy
      [...(facilities ?? [])].sort(byName).map((facility) => ({
        value: facility.id,
        label: `${facility.code} - ${facility.name}`,
      })),
    [facilities]
  )
  if (!facilities) return <FieldSkeleton label="Facility" required />
  return (
    <ComboboxField
      clearLabel="Clear Facility"
      description={searchHint(items.length, "facilities")}
      emptyMessage="No facilities found."
      items={items}
      label="Facility"
      placeholder="Search Facilities..."
      required
    />
  )
}

/** The roles of this type; once one is picked, the rights it grants show beneath. */
function RoleField({
  roles,
  roleId,
}: {
  roles: Role[]
  roleId: string | null
}) {
  const items = useMemo(
    () => roles.map((role) => ({ value: role.id, label: role.name })),
    [roles]
  )
  const labels = roles
    .find((role) => role.id === roleId)
    ?.rights.map((right) => rightLabel(right.name))
  // oxlint-disable-next-line unicorn/no-array-sort -- sorts the fresh mapped array
  const rights = labels?.sort().join(", ")

  return (
    <ComboboxField
      clearLabel="Clear Role"
      description={rights && `Grants ${rights}.`}
      emptyMessage="No roles found."
      items={items}
      label="Role"
      placeholder="Search Roles..."
      required
    />
  )
}

import { z } from "zod"

import {
  assignmentKey,
  type RightType,
  type RoleAssignment,
  toSavedAssignment,
} from "@/components/blocks/openlmis/role-assignments/role-assignments"

const roleFormFields = z.object({
  roleId: z.string().nullable(),
  programId: z.string().nullable(),
  supervisoryNodeId: z.string().nullable(),
  warehouseId: z.string().nullable(),
})

export type RoleFormValues = z.input<typeof roleFormFields>

export const EMPTY_ROLE_FORM: RoleFormValues = {
  roleId: null,
  programId: null,
  supervisoryNodeId: null,
  warehouseId: null,
}

/** The assignment the form describes, with only the ids its type uses. */
export function toRoleAssignment(
  type: RightType,
  values: RoleFormValues
): RoleAssignment {
  return toSavedAssignment({
    roleId: values.roleId ?? "",
    ...(type === "SUPERVISION" && {
      programId: values.programId,
      supervisoryNodeId: values.supervisoryNodeId,
    }),
    ...(type === "ORDER_FULFILLMENT" && { warehouseId: values.warehouseId }),
  })
}

/** Each type needs its own fields; the same role twice, in the same place, is refused. */
export function roleFormSchema(
  type: RightType,
  assigned: readonly RoleAssignment[]
) {
  const assignedKeys = new Set(assigned.map(assignmentKey))

  return roleFormFields.superRefine((values, context) => {
    const require = (path: keyof RoleFormValues, message: string) => {
      if (!values[path])
        context.addIssue({ code: "custom", path: [path], message })
    }
    if (type === "SUPERVISION") require("programId", "Choose a program.")
    if (type === "ORDER_FULFILLMENT")
      require("warehouseId", "Choose a facility.")
    require("roleId", "Choose a role.")

    if (
      values.roleId &&
      assignedKeys.has(assignmentKey(toRoleAssignment(type, values)))
    ) {
      context.addIssue({
        code: "custom",
        path: ["roleId"],
        message: "This user already has this role here.",
      })
    }
  })
}

"use client"

import { revalidateLogic, useStore } from "@tanstack/react-form"
import { useMemo } from "react"
import { z } from "zod"

import { FieldDescription, FieldGroup } from "@/components/ui/field"
import {
  mergeAssignments,
  type RoleAssignment,
} from "@/components/blocks/openlmis/role-assignments/role-assignments"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  ComboboxField,
  FieldSkeleton,
} from "@/components/openlmis/form-fields/form-fields"

export type ImportSourceUser = {
  id: string
  username: string
  firstName?: string | null
  lastName?: string | null
  roleAssignments: RoleAssignment[]
}

const importSchema = z.object({
  userId: z
    .string()
    .nullable()
    .refine(Boolean, "Choose a user to copy roles from."),
})

type ImportRolesDialogProps = {
  open: boolean
  /** The user being edited, left out of the list. */
  userId: string
  username: string
  /** The roles being edited now, to count which ones are new. */
  draft: readonly RoleAssignment[]
  /** Who roles can be copied from; the field shows a skeleton until it is set. */
  users: readonly ImportSourceUser[] | undefined
  onImport: (assignments: RoleAssignment[], fromUsername: string) => void
  onClose: () => void
}

/** Copies another user's roles into the draft; nothing is saved until the page is. */
export function ImportRolesDialog({
  open,
  onClose,
  ...props
}: ImportRolesDialogProps) {
  const { shown, dialogProps } = useDialogTarget(open || undefined, onClose)
  return (
    <FormDialog {...dialogProps()}>
      {shown && <ImportRolesForm onDone={onClose} {...props} />}
    </FormDialog>
  )
}

function ImportRolesForm({
  userId,
  username,
  draft,
  users,
  onImport,
  onDone,
}: Omit<ImportRolesDialogProps, "open" | "onClose"> & { onDone: () => void }) {
  const form = useAppForm({
    defaultValues: { userId: null as string | null },
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: importSchema },
    onSubmit: ({ value }) => {
      const from = users?.find((user) => user.id === value.userId)
      if (!from) return
      onImport(from.roleAssignments, from.username)
      onDone()
    },
  })
  const sourceId = useStore(form.store, (state) => state.values.userId)
  const source = users?.find((user) => user.id === sourceId)

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <FormDialogHeader>
        <FormDialogTitle>Import Roles</FormDialogTitle>
        <FormDialogDescription>
          Copy another user's roles to {username}. They are added to the roles
          on this page and saved with them.
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          <form.AppField name="userId">
            {() =>
              users ? (
                <UserField excludeId={userId} users={users} />
              ) : (
                <FieldSkeleton label="User" required />
              )
            }
          </form.AppField>
          {source && (
            <ImportPreview draft={draft} roles={source.roleAssignments} />
          )}
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit>Import Roles</FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

/** Reads its field from the surrounding `AppField`. */
function UserField({
  users,
  excludeId,
}: {
  users: readonly ImportSourceUser[]
  excludeId: string
}) {
  const items = useMemo(
    () =>
      users
        .filter((user) => user.id !== excludeId)
        .map((user) => {
          const name = [user.firstName, user.lastName].filter(Boolean).join(" ")
          return {
            value: user.id,
            label: name ? `${user.username} (${name})` : user.username,
          }
        }),
    [users, excludeId]
  )
  return (
    <ComboboxField
      clearLabel="Clear User"
      description={`Type to search ${items.length} users.`}
      emptyMessage="No users found."
      items={items}
      label="User"
      placeholder="Search Users..."
      required
    />
  )
}

const count = (n: number) => (n === 1 ? "1 role" : `${n} roles`)

/** How many of the chosen user's roles are new here, before anything is added. */
function ImportPreview({
  draft,
  roles,
}: {
  draft: readonly RoleAssignment[]
  roles: readonly RoleAssignment[]
}) {
  const { added, skipped } = mergeAssignments(draft, roles)
  return (
    <FieldDescription>
      {added === 0
        ? "They have no roles this user does not already have."
        : skipped === 0
          ? `Adds ${count(added)}.`
          : `Adds ${count(added)}; ${count(skipped)} this user already has.`}
    </FieldDescription>
  )
}

"use client"

import { useCallback, useMemo, useState } from "react"

import {
  assignmentKey,
  countChanges,
  mergeAssignments,
  type RoleAssignment,
} from "@/components/blocks/openlmis/role-assignments/role-assignments"

/** The roles being edited, kept apart from the saved ones until they are saved. */
export function useRoleDraft(saved: RoleAssignment[]) {
  const [draft, setDraft] = useState(saved)
  const changes = useMemo(() => countChanges(saved, draft), [saved, draft])

  const add = useCallback(
    (assignment: RoleAssignment) =>
      setDraft(
        (current) => mergeAssignments(current, [assignment]).assignments
      ),
    []
  )
  const remove = useCallback((assignment: RoleAssignment) => {
    const key = assignmentKey(assignment)
    setDraft((current) => current.filter((item) => assignmentKey(item) !== key))
  }, [])
  /** Adds another user's roles; returns how many were new and how many were already held. */
  const merge = useCallback(
    (incoming: RoleAssignment[]) => {
      const result = mergeAssignments(draft, incoming)
      setDraft(result.assignments)
      return result
    },
    [draft]
  )
  const reset = useCallback(() => setDraft(saved), [saved])

  return { draft, changes, add, remove, merge, reset }
}

"use client"

import { CopyPlusIcon, ShieldIcon } from "lucide-react"
import { useCallback, useMemo, useState } from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { AddRoleDialog } from "@/components/openlmis/user-roles-page/add-role-dialog"
import { ImportRolesDialog } from "@/components/openlmis/user-roles-page/import-roles-dialog"
import {
  byId,
  countByType,
  type Facility,
  type Program,
  type Role,
  type RoleAssignment,
  type RoleRow,
  ROLE_TABS,
  type RoleTab,
  type SupervisoryNode,
  toRoleRows,
  assignmentKey,
} from "@/components/blocks/openlmis/role-assignments/role-assignments"
import {
  type LookupStatus,
  RoleAssignmentsTable,
} from "@/components/blocks/openlmis/role-assignments/role-assignments-table"
import {
  Workspace,
  WorkspaceActions,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceFooter,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceLayout,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { Callout } from "@/components/openlmis/callout"
import { DiscardChangesDialog } from "@/components/openlmis/discard-changes-dialog"
import { PageBreadcrumbs } from "@/components/openlmis/page-breadcrumbs"

import {
  MOCK_FACILITIES,
  MOCK_NODES,
  MOCK_PROGRAMS,
  MOCK_ROLES,
  MOCK_USER_ID,
  MOCK_USERS,
  type RolesUser,
} from "@/components/openlmis/user-roles-page/mock-roles"
import { useRoleDraft } from "@/components/openlmis/user-roles-page/use-role-draft"

type UserRolesPageProps = {
  /** The user whose roles are edited. */
  user?: RolesUser
  /** Who roles can be imported from. */
  users?: readonly RolesUser[]
  roles?: readonly Role[]
  programs?: readonly Program[]
  /** Leave undefined while they load; their names show as placeholders meanwhile. */
  nodes?: readonly SupervisoryNode[]
  facilities?: readonly Facility[]
  /** Save the roles, e.g. with one request; the draft becomes the saved roles. */
  onSave?: (assignments: RoleAssignment[]) => void
  /** Leave the page, e.g. back to the users list; asked first when there are unsaved changes. */
  onCancel?: () => void
}

type Notice =
  | { kind: "removed"; row: RoleRow }
  | { kind: "imported"; added: number; from: string }
  | { kind: "saved" }

type OpenDialog =
  | { kind: "add"; tab: RoleTab }
  | { kind: "import" }
  | { kind: "discard" }

const mockUser = MOCK_USERS.find((candidate) => candidate.id === MOCK_USER_ID)

/** Edit User Roles: one draft across the four role tabs, saved together from the bar at the bottom. */
export function UserRolesPage({
  user = mockUser,
  users = MOCK_USERS,
  roles = MOCK_ROLES,
  programs = MOCK_PROGRAMS,
  nodes = MOCK_NODES,
  facilities = MOCK_FACILITIES,
  onSave,
  onCancel,
}: UserRolesPageProps) {
  // The page needs a user; the mock always has one.
  if (!user) return null
  return (
    <RolesEditor
      facilities={facilities}
      key={user.id}
      nodes={nodes}
      onCancel={onCancel}
      onSave={onSave}
      programs={programs}
      roles={roles}
      user={user}
      users={users}
    />
  )
}

function RolesEditor({
  user,
  users,
  roles,
  programs,
  nodes,
  facilities,
  onSave,
  onCancel,
}: Omit<
  Required<UserRolesPageProps>,
  "onSave" | "onCancel" | "nodes" | "facilities"
> &
  Pick<UserRolesPageProps, "onSave" | "onCancel" | "nodes" | "facilities">) {
  const [saved, setSaved] = useState(user.roleAssignments)
  const draft = useRoleDraft(saved)
  const [tab, setTab] = useState<RoleTab>(ROLE_TABS[0])
  const [dialog, setDialog] = useState<OpenDialog>()
  const [notice, setNotice] = useState<Notice>()
  const closeDialog = () => setDialog(undefined)

  const lookups = useMemo(
    () => ({
      roles: byId(roles),
      programs: byId(programs),
      nodes: nodes && byId(nodes),
      facilities: facilities && byId(facilities),
    }),
    [roles, programs, nodes, facilities]
  )
  const status = useMemo<LookupStatus>(
    () => ({
      nodes: nodes ? "ready" : "pending",
      facilities: facilities ? "ready" : "pending",
    }),
    [nodes, facilities]
  )
  const savedKeys = useMemo(() => new Set(saved.map(assignmentKey)), [saved])
  const rows = useMemo(
    () =>
      toRoleRows(draft.draft, tab.type, {
        lookups,
        savedKeys,
        homeFacilityId: user.homeFacilityId,
      }),
    [draft.draft, tab.type, lookups, savedKeys, user.homeFacilityId]
  )
  const counts = useMemo(
    () => countByType(draft.draft, lookups.roles),
    [draft.draft, lookups.roles]
  )

  const { remove } = draft
  const removeRole = useCallback(
    (row: RoleRow) => {
      remove(row.assignment)
      setNotice({ kind: "removed", row })
    },
    [remove]
  )

  const save = () => {
    onSave?.(draft.draft)
    setSaved(draft.draft)
    setNotice({ kind: "saved" })
  }
  const cancel = () => {
    if (draft.changes > 0) setDialog({ kind: "discard" })
    else onCancel?.()
  }
  const name = [user.firstName, user.lastName].filter(Boolean).join(" ")

  return (
    <WorkspaceLayout>
      <Workspace>
        <PageBreadcrumbs
          items={[
            { label: "Home", href: "#" },
            { label: "Administration" },
            { label: "Users", href: "#" },
            { label: "Roles" },
          ]}
        />
        <WorkspaceHeader>
          <WorkspaceHeading>
            <WorkspaceIcon>
              <ShieldIcon />
            </WorkspaceIcon>
            <WorkspaceTitle>Roles for {name || user.username}</WorkspaceTitle>
            <WorkspaceDescription>
              What {user.username} can do in OpenLMIS, and where.
            </WorkspaceDescription>
          </WorkspaceHeading>
          <WorkspaceActions>
            <Button
              onClick={() => setDialog({ kind: "import" })}
              size="lg"
              variant="outline"
            >
              <CopyPlusIcon data-icon="inline-start" />
              Import Roles
            </Button>
          </WorkspaceActions>
        </WorkspaceHeader>
        <WorkspaceContent>
          {notice && (
            <NoticeAlert
              notice={notice}
              onUndo={(row) => {
                draft.add(row.assignment)
                setNotice(undefined)
              }}
            />
          )}
          <Tabs
            onValueChange={(value) =>
              setTab(
                ROLE_TABS.find((item) => item.id === value) ?? ROLE_TABS[0]
              )
            }
            value={tab.id}
          >
            {/* A size container, so the tabs go two by two when four do not fit in a row. */}
            <div className="@container/tabs">
              <TabsList
                aria-label="Role types"
                className="grid h-auto w-full grid-cols-2 group-data-horizontal/tabs:h-auto @xl/tabs:flex @xl/tabs:w-fit"
              >
                {ROLE_TABS.map((item) => (
                  <TabsTrigger className="h-7" key={item.id} value={item.id}>
                    {item.label}
                    <Badge variant="secondary">{counts[item.type]}</Badge>
                  </TabsTrigger>
                ))}
              </TabsList>
            </div>
            {ROLE_TABS.map((item) => (
              <TabsContent className="pt-2" key={item.id} value={item.id}>
                {item.id === tab.id && (
                  <RoleAssignmentsTable
                    // Keyed, so each tab starts its own search, sort and paging.
                    key={item.id}
                    onAdd={() => setDialog({ kind: "add", tab: item })}
                    onRemove={removeRole}
                    rows={rows}
                    status={status}
                    tab={item}
                  />
                )}
              </TabsContent>
            ))}
          </Tabs>
        </WorkspaceContent>
      </Workspace>
      <WorkspaceFooter>
        <Button onClick={cancel} size="lg" variant="outline">
          Cancel
        </Button>
        <Button disabled={draft.changes === 0} onClick={save} size="lg">
          Save Changes
          {draft.changes > 0 && (
            <Badge variant="secondary">
              <span aria-hidden="true">{draft.changes}</span>
              <span className="sr-only">
                {draft.changes === 1
                  ? "1 unsaved change"
                  : `${draft.changes} unsaved changes`}
              </span>
            </Badge>
          )}
        </Button>
      </WorkspaceFooter>

      <AddRoleDialog
        assigned={draft.draft}
        facilities={facilities}
        hasHomeFacility={Boolean(user.homeFacilityId)}
        nodes={nodes}
        onAdd={(assignment) => {
          draft.add(assignment)
          setNotice(undefined)
        }}
        onClose={closeDialog}
        programs={programs}
        roles={roles}
        type={dialog?.kind === "add" ? dialog.tab.type : undefined}
        username={user.username}
      />
      <ImportRolesDialog
        draft={draft.draft}
        onClose={closeDialog}
        onImport={(assignments, from) => {
          const { added } = draft.merge(assignments)
          setNotice({ kind: "imported", added, from })
        }}
        open={dialog?.kind === "import"}
        userId={user.id}
        username={user.username}
        users={users}
      />
      <DiscardChangesDialog
        changes={draft.changes}
        onDiscard={() => {
          draft.reset()
          setNotice(undefined)
          closeDialog()
          onCancel?.()
        }}
        onKeepEditing={closeDialog}
        open={dialog?.kind === "discard"}
        subject={`the roles of ${user.username}`}
      />
    </WorkspaceLayout>
  )
}

/** What just happened to the draft, with Undo for a removal; it stays until the next change. */
function NoticeAlert({
  notice,
  onUndo,
}: {
  notice: Notice
  onUndo: (row: RoleRow) => void
}) {
  if (notice.kind === "saved") {
    return (
      <Callout title="Roles Saved" tone="success">
        The changes are saved.
      </Callout>
    )
  }
  if (notice.kind === "imported") {
    return (
      <Callout title="Roles Imported" tone="info">
        {notice.added === 1 ? "1 role" : `${notice.added} roles`} added from{" "}
        {notice.from}. Save to keep them.
      </Callout>
    )
  }
  return (
    <Callout
      action={
        <Button
          onClick={() => onUndo(notice.row)}
          size="sm"
          type="button"
          variant="outline"
        >
          Undo
        </Button>
      }
      title="Role Removed"
      tone="info"
    >
      {notice.row.role ?? "The role"} is removed. Save to keep the change.
    </Callout>
  )
}

